import{_ as e,o as r,c as t,a3 as i}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/performance-and-scalability.md","filePath":"core-concepts/performance-and-scalability.md"}'),s={name:"core-concepts/performance-and-scalability.md"};function l(o,a,n,c,d,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h2 id="performance-vs-scalability" tabindex="-1">Performance vs scalability <a class="header-anchor" href="#performance-vs-scalability" aria-label="Permalink to &quot;Performance vs scalability&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Performance vs scalability.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p>A service is <strong>scalable</strong> if it results in increased <strong>performance</strong> in a manner proportional to resources added. Generally, increasing performance means serving more units of work, but it can also be to handle larger units of work, such as when datasets grow.<sup><a href="http://www.allthingsdistributed.com/2006/03/a_word_on_scalability.html">1</a></sup></p><p>Another way to look at performance vs scalability:</p><ul><li>If you have a <strong>performance</strong> problem, your system is slow for a single user.</li><li>If you have a <strong>scalability</strong> problem, your system is fast for a single user but slow under heavy load.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="http://www.allthingsdistributed.com/2006/03/a_word_on_scalability.html" target="_blank" rel="noreferrer">A word on scalability</a></li><li><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/" target="_blank" rel="noreferrer">Scalability, availability, stability, patterns</a></li></ul>',7)])])}const m=e(s,[["render",l]]);export{u as __pageData,m as default};
